const __aivicBundle_17_generateInvoiceFromDeal = (() => {
  function generateInvoiceFromDeal(dealData: {
    deal_id: string;
    customer_id: string;
    customer_name: string;
    status: string;
    line_items: Array<{
      line_id: string;
      product_name: string;
      quantity: number;
      unit_price: number;
      tax_rate?: number;
      line_order?: number;
    }>;
  }): {
    invoice_id: string;
    customer_id: string;
    customer_name: string;
    deal_id: string;
    status: string;
    invoice_line_items: Array<{
      line_id: string;
      product_name: string;
      quantity: number;
      unit_price: number;
      subtotal: number;
      tax_amount: number;
      total: number;
      tax_rate: number;
      line_order: number;
    }>;
    subtotal: number;
    tax_amount: number;
    total_amount: number;
  } {
    const invoiceLineItems = dealData.line_items.map((item, index) => {
      const taxRate = item.tax_rate ?? 0.1;
      const lineOrder = item.line_order ?? index + 1;
      const subtotal = item.quantity * item.unit_price;
      const taxAmount = Math.round(subtotal * taxRate * 100) / 100;
      const total = subtotal + taxAmount;
  
      return {
        line_id: item.line_id,
        product_name: item.product_name,
        quantity: item.quantity,
        unit_price: item.unit_price,
        subtotal,
        tax_amount: taxAmount,
        total,
        tax_rate: taxRate,
        line_order: lineOrder,
      };
    });
  
    const subtotal = invoiceLineItems.reduce((sum, item) => sum + item.subtotal, 0);
    const taxAmount = invoiceLineItems.reduce((sum, item) => sum + item.tax_amount, 0);
    const totalAmount = subtotal + taxAmount;
  
    return {
      invoice_id: randomUUID(),
      customer_id: dealData.customer_id,
      customer_name: dealData.customer_name,
      deal_id: dealData.deal_id,
      status: dealData.status,
      invoice_line_items: invoiceLineItems,
      subtotal,
      tax_amount: taxAmount,
      total_amount: totalAmount,
    };
  }
  return { generateInvoiceFromDeal };
})();
