/* AIVIC_FUNCTION_BUNDLE_START owner=calculateLicenseCostComparison exports=calculateLicenseCostComparison */
const __aivicBundle_28_calculateLicenseCostComparison = (() => {
  function calculateLicenseCostComparison(
    input: LicenseCostComparisonInput
  ): LicenseCostComparisonOutput {
    // annualMaintenanceCost が null または undefined の場合、比較計算をスキップ
    if (input.annualMaintenanceCost === null || input.annualMaintenanceCost === undefined) {
      return {
        comparisonSkipped: true,
        warningMessage: '年間保守運用コストが入力されていません',
        comparisonResult: null,
        hasError: false,
      };
    }
  
    // annualMaintenanceCost が正の値の場合、3年間の総コストを比較
    const threeYears = 3;
    
    // Salesforce ライセンス費用の3年間総コスト
    const totalSalesforceThreeYearCost = input.salesforceLicenseCost * threeYears;
    
    // 自社開発システムコストの3年間総コスト
    // = 初期構築コスト + (年間保守運用コスト × 3年)
    const totalDevelopmentThreeYearCost =
      input.initialConstructionCost +
      input.annualMaintenanceCost * threeYears;
    
    // コスト削減額
    const costSavings = totalSalesforceThreeYearCost - totalDevelopmentThreeYearCost;
  
    return {
      comparisonSkipped: false,
      warningMessage: null,
      comparisonResult: {
        totalSalesforceThreeYearCost,
        totalDevelopmentThreeYearCost,
        costSavings,
      },
      hasError: false,
    };
  }
  return { calculateLicenseCostComparison };
})();
export const calculateLicenseCostComparison = __aivicBundle_28_calculateLicenseCostComparison.calculateLicenseCostComparison;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateLicenseCostComparison */
